import math
def solve(a, b, c):
    d = b*b - 4*a*c
    return ((-b + math.sqrt(d)) / (2*a), (-b - math.sqrt(d)) / (2*a))
tests = [(1, -5, 6, 'ordinary'), (1, 2, 5, 'negative discriminant'), (0, 2, -8, 'a = 0 (not quadratic)'), (1, -4, 4, 'double root')]
for a, b, c, label in tests:
    try:
        print(label, '->', solve(a, b, c))
    except Exception as e:
        print(label, '-> CRASH:', type(e).__name__, e)

def luhn(number):
    digits = [int(ch) for ch in number]
    total = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total, total % 10 == 0
for n in ('4539148803436467', '4539148803436468'):
    s, ok = luhn(n)
    print(n, '-> sum', s, '-> valid' if ok else '-> INVALID')

