for a, x in tests:
    expected = a.index(x) if x in a else -1
    got = bsearch(a, x)
    print(f'search {x} in {a}: got {got}, expected {expected}', 'OK' if got == expected else '<-- WRONG')

def is_prime(m):
    if m < 2:
        return False
    p = 2
    while p * p <= m:
        if m % p == 0:
            return False
        p += 1
    return True
first_fail = None
for n in range(0, 61):
    v = n * n + n + 41
    if not is_prime(v):
        first_fail = (n, v)
        break
